// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

interface IERC165Probe {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 seed) public {
        // Admissible domain: interfaceIds adjacent to the canonical ERC165 selector.
        // The rule is universal over this (wide-enough) window: a correctly ERC165-registered
        // contract answers true exactly at the canonical IERC165 selector, and false for any
        // other nearby selector. The window deliberately CONTAINS the bug-triggering input.
        bytes4 erc165 = type(IERC165Probe).interfaceId;
        bytes4 id = bytes4(uint32(bound(seed, uint256(uint32(erc165)), uint256(uint32(erc165)) + 15)));

        bool supported = c.supportsInterface(id);
        // General rule: support is reported exactly at the canonical ERC165 selector.
        assertTrue(supported == (id == erc165));
    }
}
